def model(points,edges,faces=None,views=None,names=None,planar=False,labels=None):
 d={'points':points,'edges':edges,'views':{'neutral':{'label':'Исходная конфигурация'},**(views or {})},'labelNames':list(points) if names is None else names}
 if faces:d['faces']=faces
 if planar:d['planar']=True
 if labels:d['labels']=labels
 return d

def planes(three=False):
 p={'u1':[-3,-2,0],'u2':[3,-2,0],'u3':[3,2,0],'u4':[-3,2,0], 'v1':[-3,0,-2],'v2':[3,0,-2],'v3':[3,0,2],'v4':[-3,0,2], 'L':[-3,0,0],'R':[3,0,0]}
 f=[['u1','u2','u3','u4'],['v1','v2','v3','v4']]
 if three:
  p.update({'w1':[0,-2,-2],'w2':[0,2,-2],'w3':[0,2,2],'w4':[0,-2,2]});f.append(['w1','w2','w3','w4'])
 return p,f

def oneplane():
 p,f=planes();return {k:p[k] for k in ['u1','u2','u3','u4']},f[:1]

def v(label,segments=None,polygon=None,points=None):
 d={'label':label}
 if segments:d['segments']=segments
 if polygon:d['polygon']=polygon
 if points:d['points']=points
 return d

def S(title,prompt,text,why,view='neutral',kind='theorem'):
 return {'title':title,'prompt':prompt,'explanation':text,'justifications':[{'kind':kind,'text':why}],'view':view}

