h=math.sqrt(32);p={'A':[0,0,0],'B':[2,h,0],'C':[8,h,0],'D':[10,0,0],'E':[1,h/2,0],'K':[4,h/2,0],'F':[9,h/2,0]}
save(27,'Трапеция с биссектрисой','Диагональ AC равнобокой трапеции ABCD (AB=CD) делит угол BAD пополам. E — середина AB; прямая через E, параллельная основаниям, пересекает AC в K и CD в F. Найдите периметр, если EK=3 см, KF=5 см.','Восстановить основания по средним линиям, боковые стороны — по биссектрисе.',model(p,[['A','B'],['B','C'],['C','D'],['D','A'],['A','C'],['E','F']],[['A','B','C','D']],{'small':v('EK — средняя линия треугольника ABC',polygon=['A','B','C'],segments=[['E','K'],['B','C']]),'large':v('KF — средняя линия треугольника ACD',polygon=['A','C','D'],segments=[['K','F'],['A','D']]),'angles':v('∠BAC=∠BCA ⇒ AB=BC',polygon=['A','B','C'])},planar=True),[
 S('Найди BC','Почему EK — средняя линия ABC?','E — середина AB, EK∥BC. По теореме о прямой через середину стороны треугольника K — середина AC, EK=BC/2. Поэтому BC=2·3=6 см.','Теорема о средней линии треугольника.','small'),
 S('Найди AD','Что теперь известно о K в треугольнике ACD?','K — середина AC, KF∥AD. Значит F — середина CD и KF=AD/2. Поэтому AD=2·5=10 см.','Теорема о средней линии треугольника.','large'),
 S('Используй биссектрису','Сравни ∠BAC и ∠BCA.','Так как AC — биссектриса BAD, ∠BAC=∠CAD. Поскольку AD∥BC, ∠CAD=∠BCA как накрест лежащие. Значит ∠BAC=∠BCA.','Определение биссектрисы; углы при параллельных прямых.','angles'),
 S('Найди боковые стороны','Какие стороны лежат напротив равных углов в ABC?','Напротив ∠BAC лежит BC, напротив ∠BCA — AB. Поэтому AB=BC=6 см. Трапеция равнобокая, следовательно CD=AB=6 см.','Против равных углов треугольника лежат равные стороны; дано AB=CD.','angles'),
 S('Сложи четыре стороны','Чему равен периметр ABCD?','P=AB+BC+CD+AD=6+6+6+10=28 см. Ответ: 28 см.','Определение периметра.','neutral')],('Как связать биссектрису с длиной боковой стороны?','Используй AD∥BC, чтобы перенести угол CAD в угол BCA. В треугольнике ABC появятся два равных угла.'))
